SELECT s.city, CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS store_sale_count, MAX(ss.sale_date) AS latest_sale_date FROM store_sales ss LEFT JOIN products p ON ss.product_id = p.id JOIN suppliers s ON p.supplier_id = s.id WHERE ARRAY_CONTAINS(p.tags, 'clearance') GROUP BY s.city, CASE WHEN s.rating >= 4.1 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END ORDER BY latest_sale_date, city, rating_bucket LIMIT 5
